import os, urllib.request, json, urllib.parse
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
tool_id='toolshed.g2.bx.psu.edu/repos/bgruening/salmon/salmon/1.10.1+galaxy4'
req=urllib.request.Request(url+'/api/tools/'+urllib.parse.quote(tool_id, safe='')+'?io_details=true', headers={'x-api-key':key})
d=json.load(urllib.request.urlopen(req, timeout=60))

def walk(inputs, prefix=''):
    for inp in inputs or []:
        name=inp.get('name'); typ=inp.get('type') or inp.get('model_class')
        print(prefix+str(name)+' ['+str(typ)+'] default='+repr(inp.get('value'))+' optional='+repr(inp.get('optional')))
        if typ=='conditional' or inp.get('model_class')=='Conditional':
            for case in inp.get('cases',[]):
                print(prefix+'  WHEN '+repr(case.get('value')))
                walk(case.get('inputs'), prefix+'    ')
        elif typ=='section' or inp.get('model_class')=='Section':
            walk(inp.get('inputs'), prefix+'  ')
        elif typ=='repeat' or inp.get('model_class')=='Repeat':
            walk(inp.get('inputs'), prefix+'  ')
        if inp.get('options') and isinstance(inp.get('options'), list):
            print(prefix+' opts', inp['options'][:5])
walk(d.get('inputs'))
print('outputs')
for out in d.get('outputs',[]): print(out)
PY"

/bin/bash -lc "python - <<'PY'
import os, urllib.request, json, urllib.parse
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
tool_id='toolshed.g2.bx.psu.edu/repos/bgruening/salmon/salmon/1.10.1+galaxy4'
d=json.load(urllib.request.urlopen(urllib.request.Request(url+'/api/tools/'+urllib.parse.quote(tool_id, safe='')+'?io_details=true', headers={'x-api-key':key}), timeout=60))
# Print conditionals without child bulk
for inp in d['inputs']:
    if inp.get('type')=='conditional':
        shallow={k:v for k,v in inp.items() if k"'!='"'cases'}
        print(json.dumps(shallow, indent=2))
        print('cases', [c.get('value') for c in inp.get('cases',[])])
        # nested conditionals shallow too
        for c in inp.get('cases',[]):
            for ii in c.get('inputs',[]):
                if ii.get('type')=='conditional':
                    print('nested under', inp['name'], 'case',c['value'], json.dumps({k:v for k,v in ii.items() if k"'!='"'cases'}, indent=2), [cc.get('value') for cc in ii.get('cases',[])])
                    for cc in ii.get('cases',[]):
                        for iii in cc.get('inputs',[]):
                            if iii.get('type')=='section':
                                for s in iii.get('inputs',[]):
                                    if s.get('type')=='conditional': print('deeper', json.dumps({k:v for k,v in s.items() if k"'!='"'cases'}, indent=2), [x.get('value') for x in s.get('cases',[])])
                            if iii.get('type')=='conditional': print('deeper', json.dumps({k:v for k,v in iii.items() if k"'!='"'cases'}, indent=2), [x.get('value') for x in iii.get('cases',[])])
PY"

